#include <bits/stdc++.h>
using namespace std;

using LL = long long;

const int NMAX = 32;
const int BMAX = 60;
const int MODULUS = 1000000007;
const LL MAX_INF = 2000000000000000000LL;

inline void normalize(int &x)
{
    if (x >= MODULUS) x -= MODULUS;
    if (x < 0) x += MODULUS;
}

struct MatrixType
{
    int matrix[MAXN][MAXN];
    int size;
    MatrixType(int n=0, int val=0)
    {
        size = n;
        for (int i=0; i<size; i++)
            for (int j=0; j<size; j++)
                matrix[i][j] = (i==j)? val : 0;
    }
    int* operator[](int row) { return matrix[row]; }
    MatrixType operator*(const MatrixType &b)
    {
        MatrixType res(size, 0);
        for (int i=0; i<size; i++)
            for (int j=0; j<size; j++)
                for (int k=0; k<size; k++)
                    normalize(res[i][k] += (LL)matrix[i][j] * b[j][k] % MODULUS);
        return res;
    }
    MatrixType operator+(const MatrixType &b)
    {
        MatrixType res(size, 0);
        for (int i=0; i<size; i++)
            for (int j=0; j<size; j++)
                res[i][j] = matrix[i][j] + b[i][j];
        return res;
    }
    bool operator==(const MatrixType &b)
    {
        if (size != b.size) return false;
        for (int i=0; i<size; i++)
            for (int j=0; j<size; j++)
                if (matrix[i][j] != b[i][j]) return false;
        return true;
    }
};

MatrixType fast_pow(MatrixType base, LL exp)
{
    MatrixType result(base.size, 1);
    while (exp)
    {
        if (exp & 1) result = result * base;
        base = base * base;
        exp >>= 1;
    }
    return result;
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    LL n;
    int k;
    cin >> n >> k;

    vector<LL> val(BMAX, 1);
    int lastIdx = BMAX;
    for (int i=1; i<BMAX; i++)
    {
        if (val[i-1] >= MAX_INF / k)
        {
            val[i] = MAX_INF;
            lastIdx = i;
            break;
        }
        val[i] = val[i-1] * k;
    }

    vector<MatrixType> shift(BMAX, MatrixType(k+1));
    shift[0] = MatrixType(k+1, 1);
    shift[1] = MatrixType(k+1);
    for (int i=0; i<k; i++)
        shift[1][i][(i-1+k)%k] = 1;
    shift[1][k][k] = 1;

    for (int i=2; i<k; i++)
        shift[i] = shift[i-1] * shift[1];

    vector<MatrixType> a(BMAX, MatrixType(k+1));
    for (int i=0; i<=k; i++)
        a[0][i][0] = 1;

    for (int i=1; i<lastIdx; i++)
    {
        MatrixType tmp = a[i-1];
        a[i] = a[i-1];
        for (int j=1; j<k; j++)
        {
            a[i] = a[i] * shift[k-1];
            a[i] = a[i] * tmp;
        }
        a[i] = a[i] * shift[k-1];
    }

    MatrixType answer(k+1);
    answer[0][k] = 1;
    answer = answer * get(n, lastIdx - 1);

    int res = 0;
    for (int i=0; i<=k; i++)
        normalize(res += answer[0][i]);

    cout << res << "\n";
}
